/** @jsxImportSource preact */
import { useEffect, useRef } from "preact/hooks";
import { mountReadingFocus, type ReadingFocusOptions } from "../../components/reading-focus/ReadingFocusEngine.js";
import type { MotionController } from "../../components/reading-focus/motion-runtime";

export function ReadingFocus({ options, className }: { options?: ReadingFocusOptions; className?: string }) {
  const host = useRef<HTMLDivElement>(null);
  const controller = useRef<MotionController | null>(null);
  useEffect(() => {
    const instance = mountReadingFocus(host.current!, options);
    controller.current = instance;
    return () => { instance.destroy(); controller.current = null; };
    // Options are updated below without remounting the state machine.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);
  useEffect(() => { controller.current?.update(options ?? {}); }, [options]);
  return <div ref={host} className={className} data-motion-component="reading-focus" />;
}

